-- Independent Dadyoom teaching supports, not claims about the contents of official books.
-- Idempotent: update only genuinely empty published lessons; add each origin/type once. Independently authored examples.
DO $dadyoom$
DECLARE
  r RECORD;
  target_id uuid;
  target_content text;
BEGIN
  FOR r IN SELECT * FROM jsonb_to_recordset('[{"n":1,"skill":"قيمة الأمانة في العمل","passage":"في موقف مستقل استلم موظف مبلغًا زائدًا عن فاتورة الخدمة، فتحقق من الحساب وأعاد الفرق إلى العميل. يدل الفعل على الأمانة بوصفها سلوكًا ملموسًا. لا تُنسب هذه القصة إلى نص القراءة أو إلى حديث شرعي غير موثق.","prompt":"أي تصرف يجسّد الأمانة؟","correct":"إعادة المبلغ الزائد للعميل","w1":"إخفاء الزيادة","w2":"تجاهل الخطأ","w3":"إتلاف الفاتورة","practice":"اكتب فقرة عن موقف عمل يظهر فيه خُلُق محمود، مع دليل من الفعل لا من الوصف العام فقط."},{"n":2,"skill":"النعت ومنعوته","passage":"في «قرأتُ تقريرًا دقيقًا» كلمة «دقيقًا» نعت منصوب يتبع منعوته «تقريرًا» في الإعراب والتنكير والتذكير والإفراد. وفي «التقريرُ الدقيقُ مفيدٌ» النعت مرفوع لتبعيته المبتدأ. نميزه عن الخبر.","prompt":"ما إعراب «دقيقًا» في «قرأت تقريرًا دقيقًا»؟","correct":"نعت منصوب","w1":"فاعل مرفوع","w2":"خبر مرفوع","w3":"مضاف إليه","practice":"اكتب أربعة أمثلة فيها نعوت، ثم طابق النعت مع المنعوت في الإعراب والتعريف والعدد والنوع."},{"n":3,"skill":"بناء فقرة حجاجية","passage":"موضوع «هل يلزم تدريب السلامة قبل دخول الورشة؟» يعرض موقفًا واضحًا ثم حجة عن الوقاية ودليلًا كحالة إجرائية قابلة للتوثيق، ثم يختتم بجملة تربط الدليل بالنتيجة. لا نذكر نسب حوادث مجهولة المصدر على أنها حقائق.","prompt":"أي عنصر يُقنع القارئ بعد عرض الرأي؟","correct":"حجة مدعومة بدليل","w1":"التكرار فقط","w2":"عنوان بعيد","w3":"حكم على المخالف","practice":"اكتب فقرة حجاجية من سبع جمل عن السلامة المهنية، برأي وسبب ومثال واعتراض وجواب."},{"n":4,"skill":"فضيلة التعاون في إنجاز المهمة","passage":"قسم فريق صيانة مدرسة العمل: راجعت طالبة قائمة القطع، وفحص آخر الأدوات بإشراف المعلم، وسجل ثالث النتائج. اكتشفوا خطأ في المقاس مبكرًا لأن الأدوار كانت واضحة. التعاون هنا تقسيم مسؤوليات وتبادل تحقق، لا ترك العمل لعضو واحد.","prompt":"ما الذي ساعد على اكتشاف خطأ المقاس؟","correct":"وضوح الأدوار وتبادل الفحص","w1":"غياب التنظيم","w2":"العمل دون نتائج","w3":"عدم الحديث","practice":"صف مهمة جماعية في ورشة، وحدد ثلاثة أدوار وكيف يتحقق الفريق من إنجازها."},{"n":5,"skill":"البدل المطابق","passage":"في «زار المهندسُ خالدٌ الورشةَ» كلمة «خالدٌ» بدل مطابق مرفوع من «المهندسُ» إذا قصد الاسمان الشخص نفسه. وفي «قابلت المهندسَ خالدًا» يكون «خالدًا» بدلًا منصوبًا. يتبع البدل المبدل منه في الإعراب.","prompt":"ما إعراب «خالدٌ» في المثال الأول؟","correct":"بدل مطابق مرفوع","w1":"مفعول به","w2":"حال منصوب","w3":"تمييز منصوب","practice":"أنشئ ثلاث جمل ببدل مطابق، ثم حدد المبدل منه والبدل وعلامتي الإعراب."},{"n":6,"skill":"موازنة منافع التعاون بين المؤسسات","passage":"اقترح ممثل شركتين مشاركة أجهزة تدريب مرتفعة الثمن. ذكر أحدهما تقليل التكلفة، ونبّه الآخر إلى ضرورة تحديد مسؤولية الصيانة والخصوصية بعقد واضح. المناقشة الجيدة تعرض فوائد ومخاطر وشروط تنفيذ، دون تعميم.","prompt":"ما الخطر الذي نبه إليه المتحدث الثاني؟","correct":"عدم وضوح مسؤوليات الصيانة والخصوصية","w1":"وجود أجهزة","w2":"زيادة التعلم","w3":"اختيار موعد","practice":"نظّم مناظرة قصيرة بين رأيين حول شراكة مهنية، مع منفعتين ومخاطرتين وضابط للتعاون."},{"n":7,"skill":"قراءة التراث مع مراعاة التوثيق","passage":"يحمل اسم «مسار اللؤلؤ» صلة بالتراث البحريني، لكن تفاصيل القراءة المدرسية تتطلب مصدرها الأصلي. في نص مستقل: «رافق متعلم مرشدًا يشرح أعمال الغوص قديمًا وطريقة حفظ الشواهد التراثية». نميز الوصف من الادعاء التاريخي الذي يحتاج مرجعًا.","prompt":"ما العمل الذي يؤديه المرشد في المثال؟","correct":"شرح أعمال الغوص القديمة","w1":"بيع أحجار صناعية","w2":"تعليم الطيران","w3":"إغلاق المعرض","practice":"اكتب وصفًا لموقع تراثي بحريني بعد استخدام مصدر موثوق، مع فصل ما شاهدته عما قرأته."},{"n":8,"skill":"التوكيد اللفظي والمعنوي","passage":"«نجح نجح الفريقُ» يتضمن توكيدًا لفظيًا بتكرار «نجح»، و«حضر العاملون كلُّهم» يتضمن توكيدًا معنويًا بكلمة «كل» متصلة بالضمير، مرفوعة تبعًا للمؤكد المرفوع. لا تُعد كل كلمة مكررة في سياق غير مقصود توكيدًا بلاغيًا.","prompt":"ما نوع التوكيد في «حضر العاملون كلهم»؟","correct":"توكيد معنوي","w1":"نعت","w2":"بدل","w3":"تمييز","practice":"اكتب مثالين لتوكيد لفظي ومعنوي، ثم أعرب أداة التوكيد المعنوي."},{"n":9,"skill":"الأطروحة والدليل والاعتراض","passage":"الأطروحة: «تساعد المحاكاة الرقمية المتدربين على تكرار المحاولة بأمان في بعض المواقف». يحتاج الدفاع عنها دليلًا من نشاط موثّق ومعرفة حدود المحاكاة، فلا نزعم أنها تغني عن كل تدريب عملي أو تلغي إشراف المختص.","prompt":"أي صياغة حجاجية أكثر اتزانًا؟","correct":"قد تفيد المحاكاة في مواقف محددة مع التدريب العملي","w1":"المحاكاة تضمن نجاح الجميع","w2":"لا حاجة أبدًا إلى معلم","w3":"كل الأجهزة متطابقة","practice":"اكتب أطروحة عن التقنية المهنية مع حجتين ودليل واعتراض موضوعي ورد معلّل."},{"n":10,"skill":"قراءة الشعر دون اختلاق شواهد","passage":"تحليل قصيدة «إلى الزلاق» يقتضي الرجوع إلى أبياتها الأصلية ووضع شاهد صحيح لكل صورة أو عاطفة. نص تدريبي مستقل: «يتذكر الصياد شاطئ طفولته حين يرى الموج عند الغروب». نستدل من العبارة على الحنين، من دون نسبتها إلى الشاعر.","prompt":"ما الشعور الأقرب إلى المثال المستقل؟","correct":"الحنين إلى المكان","w1":"اللامبالاة","w2":"الخوف من القراءة","w3":"رفض السفر","practice":"استخرج شاهدًا حقيقيًا من القصيدة مع رقم البيت، واشرح كيف يكشف عن المكان أو العاطفة."},{"n":11,"skill":"الفرق بين الأمر والنهي","passage":"«ارتدِ وسائل السلامة» أسلوب أمر يفيد الطلب، و«لا تهملْ إجراءات الفحص» نهي بـ«لا» الناهية، والفعل «تهملْ» مضارع مجزوم بالسكون. الغرض هنا الإرشاد حفاظًا على سلامة المتدرب.","prompt":"ما وظيفة «لا» في «لا تهمل إجراءات الفحص»؟","correct":"لا الناهية الجازمة","w1":"لا النافية غير العاملة","w2":"حرف نداء","w3":"أداة استثناء","practice":"اكتب ثلاث جمل أمر وثلاث جمل نهي في سياق السلامة، ثم اشرح الفرق في المعنى والإعراب."},{"n":12,"skill":"حوار الانتماء والمسؤولية","passage":"تحاورت متدربتان حول المحافظة على البيئة البحرية. اقترحت الأولى فعالية تنظيف، وأضافت الثانية تسجيل النفايات التي جُمعت لتقييم أثر المبادرة. يربط الحوار محبة الوطن بخطة ومؤشر قابل للملاحظة.","prompt":"ما المقترح الذي يجعل أثر الحملة قابلًا للتقييم؟","correct":"تسجيل النفايات المجموعة","w1":"الاكتفاء بالشعارات","w2":"عدم تدوين النتائج","w3":"إلغاء المبادرة","practice":"قدّم حوارًا شفويًا من ثماني مداخلات عن خدمة الوطن، مع توزيع الأدوار وحجة لكل اقتراح."}]'::jsonb) AS x(
    n integer,skill text,passage text,prompt text,correct text,w1 text,w2 text,w3 text,practice text
  ) LOOP
    SELECT l.id,l.content INTO STRICT target_id,target_content
    FROM public.lessons l
    JOIN public.units u ON u.id=l.unit_id
    JOIN public.grades g ON g.id=u.grade_id AND g.grade_number=11
    JOIN public.curricula cu ON cu.id=g.curriculum_id AND cu.academic_year='2026-2027' AND cu.id='9a42a857-58d7-428b-80f7-c02a52e69f6b'
    JOIN public.countries c ON c.id=cu.country_id AND c.code='BH'
    WHERE u.semester=1 AND u.semester=1 AND l.sort_order=r.n AND l.status='published'
    FOR UPDATE OF l;
    IF coalesce(trim(target_content),'')='' THEN
      UPDATE public.lessons SET
        content='ضاديوم — إثراء مستقل أصلي للصف الثامن، الفصل الأول. لا يمثل النص الوزاري الأصلي ولا يثبت مطابقة العنوان للمصدر.'||E'\n\n'||
          'المهارة: '||r.skill||E'\n\n'||
          'النموذج التعليمي والشرح: '||r.passage||E'\n\n'||
          'أهداف التعلم: يحدد المتعلم شاهدًا صحيحًا ويشرح دلالته، ويميّز بين الفكرة والدليل، ثم ينتج كتابة مناسبة للمهارة.'||E'\n\n'||
          'سؤال الفهم: '||r.prompt||E'\n\n'||
          'التطبيق الكتابي: '||r.practice||E'\n\n'||
          'التمايز: المبتدئ يحصل على كلمات مفتاحية وبداية جملة؛ المتوسط يجيب بدليل مستقل؛ المتقدم يقارن بين صياغتين ويبرر تحسيناته.'||E'\n\n'||
          'مراجعة المعلم: تحقق من صحة الاستدلال والإملاء وعلامات الترقيم والترابط. لا تُمنح درجة جودة تلقائية لمجرد تسليم المهمة.'||E'\n\n'||
          'تنبيه المصدر: راجع العنوان المستورد والكتاب الرسمي قبل وصف هذا التدريب بأنه مطابق للمنهج.',
        updated_at=now()
      WHERE id=target_id;
    END IF;
    IF EXISTS (SELECT 1 FROM public.lessons WHERE id=target_id AND content LIKE 'ضاديوم — إثراء مستقل أصلي للصف الثامن%') THEN
      INSERT INTO public.lesson_activities (lesson_id,title,activity_type,section,prompt,content,answer,activity_order,points,is_required,is_published)
      SELECT target_id,'فهم النص الإثرائي','multiple_choice','assessment',r.prompt,
        jsonb_build_object('origin','DADYOOM_BH_TECH_G11_T1_ORIGINAL_20261008','notOfficialBook',true,'ocrReview','pending','options',jsonb_build_array(r.correct,r.w1,r.w2,r.w3)),
        jsonb_build_object('correct',r.correct),
        coalesce((SELECT max(activity_order) FROM public.lesson_activities WHERE lesson_id=target_id),0)+1,5,true,true
      WHERE NOT EXISTS (SELECT 1 FROM public.lesson_activities WHERE lesson_id=target_id AND activity_type='multiple_choice' AND content->>'origin'='DADYOOM_BH_TECH_G11_T1_ORIGINAL_20261008');
      INSERT INTO public.lesson_activities (lesson_id,title,activity_type,section,prompt,content,answer,activity_order,points,is_required,is_published)
      SELECT target_id,'كتابة تطبيقية بمراجعة المعلم','writing','practice',r.practice,
        jsonb_build_object('origin','DADYOOM_BH_TECH_G11_T1_ORIGINAL_20261008','notOfficialBook',true,'humanReviewRequired',true,'text',r.practice,'skillQualityAutoVerified',false),
        jsonb_build_object('grading_mode','completion_only_reference','model_answer','لا تكفي المطابقة النصية؛ يصحح المعلم ملاءمة الأفكار والدليل والترابط.'),
        coalesce((SELECT max(activity_order) FROM public.lesson_activities WHERE lesson_id=target_id),0)+1,5,true,true
      WHERE NOT EXISTS (SELECT 1 FROM public.lesson_activities WHERE lesson_id=target_id AND activity_type='writing' AND content->>'origin'='DADYOOM_BH_TECH_G11_T1_ORIGINAL_20261008');
    END IF;
  END LOOP;
END
$dadyoom$;